/**
 * Sleep voice guidance (TestFlight reports 4 and 5). The cues and their recordings come from
 * data/narration.ts, generated by scripts/generate-narration.cjs. This file holds the timing rules
 * so they can be tested without audio.
 */

export type NarrationCue = {
  /** Seconds from the start, or 'end' for 30 seconds before the session ends. */
  at?: number | 'end';
  /** Breath cues play as the breath changes phase, during the opening breaths only. */
  phase?: 'inhale' | 'exhale';
  /** Length of the recording. */
  seconds: number;
  file: number;
};

export type NarrationScripts = Record<string, Record<string, NarrationCue[]>>;

/** The closing line starts this many seconds before the end. */
export const END_LEAD_SECONDS = 30;
/** The soundscape plays at this share of its volume while the voice speaks. */
export const VOICE_DUCK = 0.35;

export function narrationLanguage(language: string | undefined): 'en' | 'el' {
  return language?.toLowerCase().startsWith('el') ? 'el' : 'en';
}

/** When a timed cue starts in a session of `total` seconds, or null for a breath cue. */
export function cueStart(cue: NarrationCue, total: number): number | null {
  if (cue.at === undefined) return null;
  if (cue.at === 'end') return Math.max(0, total - END_LEAD_SECONDS);
  return cue.at;
}

/**
 * The timed cue whose start falls in (from, to]. Starts at 0 count when `from` is below 0, so the
 * welcome plays as the session opens. A cue that would run past the end, or into the closing
 * line, is skipped, which keeps a short session from talking over itself.
 */
export function dueCue(
  cues: NarrationCue[],
  from: number,
  to: number,
  total: number,
): NarrationCue | undefined {
  const end = Math.max(0, total - END_LEAD_SECONDS);
  return cues.find((c) => {
    const start = cueStart(c, total);
    if (start === null || start <= from || start > to) return false;
    return c.at === 'end' || start + c.seconds <= end;
  });
}

/** Breath cues play until the second timed line ("keep going on your own"). */
export function breathCuesUntil(cues: NarrationCue[], total: number): number {
  const starts = cues
    .map((c) => cueStart(c, total))
    .filter((s): s is number => s !== null)
    .sort((a, b) => a - b);
  return starts[1] ?? 0;
}

export function breathCue(
  cues: NarrationCue[],
  phase: string,
  elapsed: number,
  total: number,
): NarrationCue | undefined {
  if (elapsed >= breathCuesUntil(cues, total)) return undefined;
  return cues.find((c) => c.phase === phase);
}
